#include "mk61_app.h"
#include <cstdint>
#include <cstdio>
#include <cstring>
namespace {
uint16_t word(unsigned address) { return *(const volatile uint16_t*)(uintptr_t)address; }
const void* data(char a,char b) {
 using Lookup=void*(*)(const uint16_t*,uint32_t);
 auto lookup=(Lookup)(uintptr_t)word(0x18);
 return lookup((const uint16_t*)(uintptr_t)word(0x16),(uint8_t)a|((uint32_t)(uint8_t)b<<8));
}
}
int main() {
 const auto* services=mk61_app_get_services(mk61_api,MK61_SERVICE_CAP_DEBUG_IO);
 if(!services) return 1;
 unsigned version=*(const volatile uint8_t*)(uintptr_t)0x13;
 char text[256];const auto* revision=(const uint32_t*)data('G','R');
 auto f=(uintptr_t)data('S','F'),d=(uintptr_t)data('S','D');
 const auto* copyright=(const char*)data('C','R');
 unsigned n=0;
 auto add=[&](const char* s) { while(*s && n+1<sizeof(text)) text[n++]=*s++; };
 auto hex=[&](uint32_t value) { for(int bit=28;bit>=0;bit-=4) text[n++]="0123456789ABCDEF"[(value>>bit)&15]; };
 add("RP2040_ROM_VERSION=0x");hex(version);add(" GIT=");hex(revision && (uintptr_t)revision<0x4000?*revision:0);
 add(" FLOAT_TABLE=");hex(f);add(" DOUBLE_TABLE=");hex(d);add("\nROM_COPYRIGHT=");
 if(copyright && (uintptr_t)copyright<0x4000) add(copyright);
 add("\n");for(unsigned at=0;at<n;at+=96) services->call(MK61_SERVICE_DEBUG_WRITE,n-at<96?n-at:96,0,0,text+at);return 0;
}
